// Screen 18 of 29. Generated by Google Stitch, source folder 18-camera_capture.
// Rebuilt 3 August 2026. The generated version was a stub: the viewfinder was
// `Container(color: Colors.grey[900])` and the shutter was a decorative circle
// with no handler.
//
// ── THE ONE RULE THIS SCREEN EXISTS TO ENFORCE ──────────────────────────────
// CAMERA ONLY. THERE IS NO GALLERY BUTTON, AND THERE MUST NEVER BE ONE.
//
// The entire damage evidence system rests on a photograph being taken now, in
// this room, and timestamped by the server. A gallery upload could be any
// image from any time. If somebody later asks for "just let them pick from
// their photos", the answer is no, and this comment is why.
//
// ── MEMORY. THIS APP HAS BEEN KILLED BY iOS JETSAM BEFORE ───────────────────
// A phone photograph is 4 to 8 MB decoded and a seven room capture wants seven
// of them. The compress-to-temp-file-then-upload-from-file path lives in
// StayEvidenceService and must not be short circuited here. This screen holds
// ONE XFile at a time and hands it straight over.
//
// The CameraController is disposed in dispose() AND released when the app goes
// to the background, because a live camera in the background is exactly what
// the OS kills an app for.
import 'dart:io';

import 'package:camera/camera.dart';
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import '../models/stay_enums.dart';

class CameraCaptureScreen extends StatefulWidget {
  const CameraCaptureScreen({
    super.key,
    this.room = '',
    this.guidance,
    this.kind = CaptureKind.guestCheckIn,
    this.referencePhotoUrl,
    this.onCaptured,
  });

  /// The room being photographed, for example 'Bedroom 1'.
  final String room;

  /// One sentence telling the guest what to point at. Generated once per
  /// property, not per guest.
  final String? guidance;

  final CaptureKind kind;

  /// On check out, the guest's OWN arrival photograph of this room, shown as a
  /// faint overlay so the two sets line up. Two matched photographs are a
  /// comparison. Two unmatched ones are just more to argue about.
  final String? referencePhotoUrl;

  /// Receives the captured file. The caller passes it to
  /// StayEvidenceService.capture, which compresses and uploads it.
  final Future<void> Function(File photo)? onCaptured;

  @override
  State<CameraCaptureScreen> createState() => _CameraCaptureScreenState();
}

class _CameraCaptureScreenState extends State<CameraCaptureScreen>
    with WidgetsBindingObserver {
  CameraController? _controller;
  Future<void>? _initFuture;
  bool _busy = false;
  String? _error;
  double _ghostOpacity = 0.35;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _start();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _controller?.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    final c = _controller;
    if (c == null || !c.value.isInitialized) return;
    if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused) {
      // Release the camera rather than hold it in the background. Holding it
      // is a fast route to being killed for memory.
      c.dispose();
      _controller = null;
      if (mounted) setState(() {});
    } else if (state == AppLifecycleState.resumed) {
      _start();
    }
  }

  Future<void> _start() async {
    try {
      final cameras = await availableCameras();
      if (!mounted) return;
      if (cameras.isEmpty) {
        setState(() => _error = 'No camera found on this device.');
        return;
      }
      final back = cameras.firstWhere(
        (c) => c.lensDirection == CameraLensDirection.back,
        orElse: () => cameras.first,
      );
      final c = CameraController(
        back,
        // Medium, not max. The photograph is compressed to 1600px before
        // upload anyway, so capturing at full sensor resolution only buys a
        // larger peak memory spike.
        ResolutionPreset.high,
        enableAudio: false,
      );
      _controller = c;
      _initFuture = c.initialize();
      await _initFuture;
      if (!mounted) return;
      setState(() => _error = null);
    } on CameraException catch (e) {
      if (!mounted) return;
      setState(() => _error = _friendlyError(e));
    }
  }

  String _friendlyError(CameraException e) {
    if (e.code == 'CameraAccessDenied' ||
        e.code == 'CameraAccessDeniedWithoutPrompt') {
      return 'GoOuts needs permission to use the camera so you can take these '
          'photographs. You can allow it in your phone settings.';
    }
    return 'The camera could not be opened. Please try again.';
  }

  Future<void> _shoot() async {
    final c = _controller;
    if (c == null || !c.value.isInitialized || _busy) return;
    setState(() => _busy = true);
    try {
      final shot = await c.takePicture();
      if (!mounted) return;
      // Hand the file straight over. Do NOT read it into memory here: the
      // compression path in StayEvidenceService writes a temp file and uploads
      // from it, which is what keeps one image in memory at a time.
      await widget.onCaptured?.call(File(shot.path));
      if (!mounted) return;
      Navigator.of(context).pop(true);
    } on CameraException {
      if (!mounted) return;
      setState(() {
        _busy = false;
        _error = 'That photograph could not be saved. Please try again.';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final guidance = widget.guidance ??
        (widget.room.isEmpty
            ? 'Capture the whole room in one photograph.'
            : '${widget.room}. Stand in the doorway and capture the whole '
                'room.');

    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        fit: StackFit.expand,
        children: [
          _viewfinder(),
          if (widget.referencePhotoUrl != null) _ghost(),
          _topBar(guidance),
          _bottomControls(),
          if (_error != null) _errorOverlay(),
        ],
      ),
    );
  }

  Widget _viewfinder() {
    final c = _controller;
    if (c == null || !c.value.isInitialized) {
      return const ColoredBox(
        color: Colors.black,
        child: Center(
          child: CircularProgressIndicator(color: Colors.white54),
        ),
      );
    }
    return FittedBox(
      fit: BoxFit.cover,
      child: SizedBox(
        width: c.value.previewSize?.height ?? 1,
        height: c.value.previewSize?.width ?? 1,
        child: CameraPreview(c),
      ),
    );
  }

  /// The check out overlay. This is what makes the before and after sets
  /// genuinely comparable rather than two unrelated piles of photographs.
  Widget _ghost() => Positioned.fill(
        child: IgnorePointer(
          child: Opacity(
            opacity: _ghostOpacity,
            child: Image.network(
              widget.referencePhotoUrl!,
              fit: BoxFit.cover,
              // Decoded at preview size, not full size.
              cacheWidth: 1080,
              errorBuilder: (_, __, ___) => const SizedBox.shrink(),
            ),
          ),
        ),
      );

  Widget _topBar(String guidance) => SafeArea(
        child: Column(
          children: [
            Row(
              children: [
                IconButton(
                  icon: const Icon(Icons.close, color: Colors.white, size: 30),
                  onPressed: () => Navigator.of(context).pop(false),
                ),
                const Spacer(),
              ],
            ),
            Container(
              margin: const EdgeInsets.symmetric(horizontal: 16),
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: Colors.black.withValues(alpha: 0.7),
                borderRadius: BorderRadius.circular(12),
              ),
              child: Text(
                guidance,
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                  color: Colors.white,
                  fontWeight: FontWeight.w500,
                  height: 1.4,
                ),
              ),
            ),
            if (widget.referencePhotoUrl != null) _ghostSlider(),
          ],
        ),
      );

  Widget _ghostSlider() => Container(
        margin: const EdgeInsets.fromLTRB(16, 10, 16, 0),
        padding: const EdgeInsets.symmetric(horizontal: 12),
        decoration: BoxDecoration(
          color: Colors.black.withValues(alpha: 0.6),
          borderRadius: BorderRadius.circular(24),
        ),
        child: Row(
          children: [
            Text('Your arrival photo',
                style: GoogleFonts.inter(color: Colors.white70, fontSize: 12)),
            Expanded(
              child: Slider(
                value: _ghostOpacity,
                min: 0,
                max: 0.7,
                activeColor: Colors.white,
                inactiveColor: Colors.white24,
                onChanged: (v) => setState(() => _ghostOpacity = v),
              ),
            ),
          ],
        ),
      );

  Widget _bottomControls() => Align(
        alignment: Alignment.bottomCenter,
        child: Container(
          padding: const EdgeInsets.only(top: 40, bottom: 40),
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [
                Colors.transparent,
                Colors.black.withValues(alpha: 0.5),
              ],
            ),
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                'Photograph the room, not people',
                style: GoogleFonts.inter(
                    color: Colors.white70, fontSize: 12),
              ),
              const SizedBox(height: 20),
              // NO GALLERY BUTTON. See the header.
              _shutter(),
            ],
          ),
        ),
      );

  Widget _shutter() {
    final ready = _controller?.value.isInitialized ?? false;
    return GestureDetector(
      onTap: ready && !_busy ? _shoot : null,
      child: Container(
        height: 80,
        width: 80,
        padding: const EdgeInsets.all(4),
        decoration: BoxDecoration(
          shape: BoxShape.circle,
          border: Border.all(
            color: ready ? Colors.white : Colors.white38,
            width: 4,
          ),
        ),
        child: _busy
            ? const Padding(
                padding: EdgeInsets.all(10),
                child: CircularProgressIndicator(
                    color: Colors.white, strokeWidth: 3),
              )
            : Container(
                decoration: BoxDecoration(
                  color: ready ? Colors.white : Colors.white38,
                  shape: BoxShape.circle,
                ),
              ),
      ),
    );
  }

  Widget _errorOverlay() => Positioned.fill(
        child: ColoredBox(
          color: Colors.black.withValues(alpha: 0.85),
          child: Center(
            child: Padding(
              padding: const EdgeInsets.all(32),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Icon(Icons.photo_camera_outlined,
                      color: Colors.white54, size: 44),
                  const SizedBox(height: 16),
                  Text(
                    _error!,
                    textAlign: TextAlign.center,
                    style: GoogleFonts.inter(
                        color: Colors.white, fontSize: 14, height: 1.5),
                  ),
                  const SizedBox(height: 20),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      TextButton(
                        onPressed: () => Navigator.of(context).pop(false),
                        child: Text('Go back',
                            style:
                                GoogleFonts.inter(color: Colors.white70)),
                      ),
                      const SizedBox(width: 12),
                      ElevatedButton(
                        onPressed: () {
                          setState(() => _error = null);
                          _start();
                        },
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.white,
                          foregroundColor: Colors.black,
                        ),
                        child: Text('Try again',
                            style: GoogleFonts.inter(
                                fontWeight: FontWeight.w600)),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
        ),
      );
}
